{ const P="assets/photos/plus/";
const F=(s,c,ce,cr,cre,m)=>[{src:P+s,cap:c,credit:cr,...(m?{maxw:m}:{})},{src:P+s,cap:ce,credit:cre,...(m?{maxw:m}:{})}];
const fig=(id,hf,he,f)=>({[id]:{fr:{[hf]:f[0]},en:{[he]:f[1]}}});
[
 fig("mansa","Tombouctou, ville de savoir","Timbuktu, city of learning",F("djinguereber.jpg","La mosquée de Djingareyber, à Tombouctou, construite vers 1327 sous Mansa Moussa. Ses murs en banco doivent être recrépis régulièrement par les habitants.","The Djinguereber Mosque in Timbuktu, built around 1327 under Mansa Musa. Its mud-brick walls must be regularly replastered by the inhabitants.","Photo : upyernoz — CC BY 2.0","Photo: upyernoz — CC BY 2.0")),
 fig("mansa","Tombouctou face aux destructions","Timbuktu in the face of destruction",F("timbuktu-manuscript.jpg","Un manuscrit de Tombouctou contenant des tables astronomiques. Les bibliothèques de la ville conservent des textes sur l'astronomie, les mathématiques, la médecine et le droit.","A Timbuktu manuscript containing astronomical tables. The city's libraries hold texts on astronomy, mathematics, medicine and law.","Institut Ahmed Baba — domaine public","Ahmed Baba Institute — public domain")),
 fig("cleopatra","Une reine grecque en Égypte","A Greek queen in Egypt",F("cleopatra-berlin.jpg","Le portrait de Cléopâtre VII conservé à l'Altes Museum de Berlin (vers 40-30 avant notre ère), l'un des rares portraits sculptés que l'on attribue avec assurance à la reine. Elle porte la coiffure « en melon » et le bandeau royal grecs.","The portrait of Cleopatra VII in the Altes Museum, Berlin (around 40–30 BCE), one of the few sculpted portraits confidently attributed to the queen. She wears the Greek \"melon\" hairstyle and royal diadem.","Photo : José Luiz — domaine public","Photo: José Luiz — public domain","400px")),
 fig("cleopatra","Une reine savante qui parlait la langue de son peuple","A learned queen who spoke her people's language",F("dendera-cleopatra.jpg","Cléopâtre (à gauche) et son fils Césarion, représentés en pharaons sur le mur du temple d'Hathor à Dendérah. Pour ses sujets égyptiens, la reine grecque se montrait dans le style des anciens rois.","Cleopatra (left) and her son Caesarion, shown as pharaohs on the wall of the temple of Hathor at Dendera. For her Egyptian subjects, the Greek queen presented herself in the style of the ancient kings.","Photo : Olaf Tausch — CC BY 3.0","Photo: Olaf Tausch — CC BY 3.0","420px")),
 fig("zimbabwe","Une prouesse sans mortier","A feat without mortar",F("zimbabwe-wall.jpg","Le mur extérieur du Grand Enclos, fait de blocs de granit empilés sans mortier. Il atteint 11 mètres de haut par endroits.","The outer wall of the Great Enclosure, built of granite blocks stacked without mortar. It reaches 11 metres high in places.","Photo : Jens Klinzing — CC BY 3.0","Photo: Jens Klinzing — CC BY 3.0")),
 fig("zimbabwe","Les oiseaux de pierre, symbole d'une nation","The stone birds, symbol of a nation",F("zimbabwe-birds.jpg","Trois des oiseaux en stéatite du Grand Zimbabwe, photographiés par l'explorateur James Theodore Bent lors des fouilles de 1891, peu avant que plusieurs d'entre eux soient emportés hors du pays.","Three of Great Zimbabwe's soapstone birds, photographed by the explorer James Theodore Bent during the 1891 excavations, shortly before several of them were taken out of the country.","J. T. Bent, The Ruined Cities of Mashonaland (1892) — domaine public","J. T. Bent, The Ruined Cities of Mashonaland (1892) — public domain")),
 fig("pompeii","Le Vésuve aujourd'hui","Vesuvius today",F("vesuvius-pompeii.jpg","Le Vésuve vu depuis les ruines de Pompéi, à une dizaine de kilomètres. Le volcan domine toujours la baie de Naples et ses millions d'habitants.","Vesuvius seen from the ruins of Pompeii, about ten kilometres away. The volcano still towers over the Bay of Naples and its millions of inhabitants.","Photo : Jebulon — CC0","Photo: Jebulon — CC0")),
 fig("pompeii","Des corps qui racontent","Bodies that tell a story",F("pompeii-casts.jpg","Des moulages de victimes de Pompéi photographiés au XIXe siècle par Giorgio Sommer, peu après l'invention de la technique de Fiorelli.","Casts of Pompeii victims photographed in the 19th century by Giorgio Sommer, shortly after Fiorelli invented the technique.","Giorgio Sommer — Metropolitan Museum of Art, CC0","Giorgio Sommer — Metropolitan Museum of Art, CC0")),
 fig("ibnbattuta","La Rihla, un récit dicté de mémoire","The Rihla, an account dictated from memory",F("rihla-manuscript.jpg","Deux pages d'un manuscrit de la Rihla mise en forme par Ibn Juzayy, conservé à la Bibliothèque nationale de France.","Two pages of a manuscript of the Rihla as written up by Ibn Juzayy, held at the Bibliothèque nationale de France.","Bibliothèque nationale de France — CC BY-SA 4.0","Bibliothèque nationale de France — CC BY-SA 4.0")),
 fig("goree","La Maison des Esclaves","The House of Slaves",F("goree-door.jpg","La cour de la Maison des Esclaves, avec son escalier à double volée. Au fond du couloir central s'ouvre la « porte du voyage sans retour », face à l'océan.","The courtyard of the House of Slaves, with its double staircase. At the end of the central corridor opens the \"door of no return\", facing the ocean.","Photo : John Crane — CC BY 2.0","Photo: John Crane — CC BY 2.0")),
 fig("goree","Une île convoitée pendant quatre siècles","An island fought over for four centuries",F("goree-1685.jpg","Gorée et la côte voisine vues par le cartographe français Alain Manesson Mallet en 1685, à l'époque où l'île venait de passer aux mains des Français.","Gorée and the nearby coast as seen by the French cartographer Alain Manesson Mallet in 1685, shortly after the island passed into French hands.","Alain Manesson Mallet (1685) — domaine public","Alain Manesson Mallet (1685) — public domain","380px"))
].forEach(addFig);
}

addParas({
 mansa:{fr:{"D'où venait l'or du Mali ?":"Cet or africain traversait ensuite le Sahara puis la Méditerranée. Il servait à frapper les dinars du monde musulman, mais aussi des monnaies européennes célèbres, comme le florin de Florence ou le ducat de Venise. Selon certaines estimations, une grande partie de l'or en circulation autour de la Méditerranée à la fin du Moyen Âge venait d'Afrique de l'Ouest."},
        en:{"Where did Mali's gold come from?":"This African gold then crossed the Sahara and the Mediterranean. It was used to mint the dinars of the Muslim world, but also famous European coins such as the Florentine florin and the Venetian ducat. By some estimates, much of the gold circulating around the Mediterranean in the late Middle Ages came from West Africa."}},
 cleopatra:{fr:{"Actium et la fin d'un monde":"La victoire sur Cléopâtre a laissé une trace dans notre calendrier. En 27 avant notre ère, Octave reçoit le titre d'Auguste. Quelques années plus tard, le Sénat romain donne son nom au sixième mois de l'ancien calendrier romain, choisi notamment parce qu'Alexandrie était tombée pendant ce mois-là : c'est l'origine de notre mois d'août.",
               "Une reine savante qui parlait la langue de son peuple":"Alexandrie abritait aussi la plus célèbre bibliothèque de l'Antiquité, qui aurait rassemblé des centaines de milliers de rouleaux. En 48 avant notre ère, lors des combats de César dans la ville, un incendie aurait détruit des entrepôts de livres près du port. L'ampleur des pertes reste discutée, car la bibliothèque a continué d'exister pendant des siècles avant de décliner progressivement."},
            en:{"Actium and the end of a world":"The victory over Cleopatra left a mark on our calendar. In 27 BCE Octavian received the title Augustus. A few years later the Roman Senate gave his name to the sixth month of the old Roman calendar, chosen partly because Alexandria had fallen in that month: this is the origin of our month of August.",
               "A learned queen who spoke her people's language":"Alexandria was also home to the most famous library of antiquity, said to have held hundreds of thousands of scrolls. In 48 BCE, during Caesar's fighting in the city, a fire is said to have destroyed book warehouses near the harbour. The extent of the losses is debated, since the library went on existing for centuries before gradually declining."}},
 zimbabwe:{fr:{"Khami, l'héritière du Grand Zimbabwe":"Au XVIIe siècle, Khami est détruite lors de conflits, et à la fin du siècle, un nouveau pouvoir s'impose dans la région : l'empire Rozvi, fondé par le chef Changamire Dombo. Ses guerriers repoussent les Portugais du plateau, et ses dirigeants construisent à leur tour des enceintes de pierre, prolongeant une tradition vieille de plusieurs siècles.",
              "Des maisons de pierre":"Le site se trouve près de la ville de Masvingo, à environ 300 kilomètres au sud de la capitale, Harare. Un petit musée installé sur place présente des objets découverts lors des fouilles, dont plusieurs oiseaux de pierre revenus au pays. Chaque année, de nombreux écoliers zimbabwéens viennent y découvrir l'histoire de leurs ancêtres."},
           en:{"Khami, heir to Great Zimbabwe":"In the 17th century Khami was destroyed in conflicts, and by the end of the century a new power dominated the region: the Rozvi empire, founded by the chief Changamire Dombo. Its warriors drove the Portuguese from the plateau, and its rulers in turn built stone enclosures, continuing a tradition several centuries old.",
              "Houses of stone":"The site lies near the town of Masvingo, about 300 kilometres south of the capital, Harare. A small museum on site displays objects found during excavations, including several stone birds returned to the country. Every year many Zimbabwean schoolchildren come to discover the history of their ancestors."}},
 pompeii:{fr:{"Herculanum et les rouleaux carbonisés":"Les progrès continuent. En 2025, des chercheurs ont réussi à lire, sans dérouler le papyrus, le titre complet de l'un de ces rouleaux : un ouvrage du philosophe Philodème consacré aux vices. C'était la première fois que l'on identifiait ainsi l'auteur et le titre d'un rouleau d'Herculanum resté fermé depuis l'éruption.",
             "Trois siècles de fouilles":"Pompéi accueille aujourd'hui environ quatre millions de visiteurs par an, ce qui fait de lui l'un des sites archéologiques les plus visités au monde. Pour protéger les ruines, la direction du parc a instauré en 2024 une limite de 20 000 visiteurs par jour et des billets nominatifs. La conservation de cette ville fragile, exposée au soleil, à la pluie et à la végétation, est un défi permanent."},
          en:{"Herculaneum and the charred scrolls":"Progress continues. In 2025 researchers managed to read, without unrolling the papyrus, the full title of one of these scrolls: a work on vices by the philosopher Philodemus. It was the first time the author and title of a Herculaneum scroll still closed since the eruption had been identified this way.",
             "Three centuries of excavation":"Pompeii now welcomes about four million visitors a year, making it one of the most visited archaeological sites in the world. To protect the ruins, the park introduced in 2024 a limit of 20,000 visitors a day and named tickets. Preserving this fragile city, exposed to sun, rain and vegetation, is a constant challenge."}},
 ibnbattuta:{fr:{"Jusqu'en Chine":"Il décrit avec admiration le port de Quanzhou, qu'il appelle Zaytun, l'un des plus grands du monde à l'époque, où il dit avoir vu une centaine de grandes jonques et d'innombrables petits bateaux. Les vestiges de ce port, qui accueillait des marchands venus d'Arabie, de Perse et d'Inde, sont inscrits au patrimoine mondial de l'UNESCO depuis 2021.",
                 "Voyager au XIVe siècle":"Les dangers étaient nombreux. Sur la côte ouest de l'Inde, Ibn Battuta est attaqué par des pirates qui lui prennent presque tout, ne lui laissant, raconte-t-il, que ses vêtements. En Anatolie, il manque de mourir de froid dans la neige. Ailleurs, il échappe de justesse à des brigands ou tombe gravement malade, mais repart chaque fois vers de nouvelles destinations."},
             en:{"As far as China":"He describes with admiration the port of Quanzhou, which he calls Zaytun, one of the largest in the world at the time, where he says he saw a hundred large junks and countless small boats. The remains of this port, which welcomed merchants from Arabia, Persia and India, have been a UNESCO World Heritage Site since 2021.",
                 "Travelling in the 14th century":"The dangers were many. On India's west coast Ibn Battuta was attacked by pirates who took almost everything, leaving him, he says, only his clothes. In Anatolia he nearly froze to death in the snow. Elsewhere he narrowly escaped bandits or fell seriously ill, but each time set off again for new destinations."}},
 goree:{fr:{"Mémoire et débat historique":"Boubacar Joseph Ndiaye, le conservateur qui a fait connaître la Maison des Esclaves au monde entier, est mort en 2009. Son successeur, Eloi Coly, a poursuivi son travail d'accueil et de transmission auprès des visiteurs. La maison est aussi devenue un lieu d'enseignement, où des historiens et des enseignants viennent expliquer la traite et ses débats.",
            "Signares, abolition et citoyens":"Les signares étaient réputées pour leur élégance, leurs grandes coiffes et leurs bijoux. Leur héritage survit dans une tradition festive : le fanal. À l'origine, les signares se rendaient à la messe de Noël précédées de lanternes portées par leurs serviteurs. Ces lanternes sont devenues de grandes constructions lumineuses en forme de bateaux ou de maisons, promenées en procession à Saint-Louis et à Gorée."},
        en:{"Memory and historical debate":"Boubacar Joseph Ndiaye, the curator who made the House of Slaves known worldwide, died in 2009. His successor, Eloi Coly, continued his work of welcoming visitors and passing on the story. The house has also become a place of teaching, where historians and teachers come to explain the slave trade and the debates around it.",
            "Signares, abolition and citizens":"Signares were famous for their elegance, their tall headdresses and their jewellery. Their legacy survives in a festive tradition: the fanal. Originally signares went to Christmas mass preceded by lanterns carried by their servants. These lanterns became large illuminated constructions shaped like boats or houses, paraded through Saint-Louis and Gorée."}}
});
